// LoginPage.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import { loginUser } from "../auth";

export default function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleLogin = async () => {
    try {
      await loginUser(username, password);
      toast.success("Login successful");
      navigate("/student/dashboard"); // or decide based on role
    } catch (err) {
      toast.error("Login failed: " + err.message);
    }
  };

  return (
    <div className="max-w-md mx-auto mt-20 p-6 bg-slate-800 rounded-xl shadow-xl">
      <h2 className="text-3xl font-semibold mb-4">Login</h2>
      <input type="text" placeholder="Username" className="input" value={username} onChange={(e) => setUsername(e.target.value)} />
      <input type="password" placeholder="Password" className="input" value={password} onChange={(e) => setPassword(e.target.value)} />
      <button onClick={handleLogin} className="btn bg-green-500 hover:bg-green-600 w-full">Log In</button>
    </div>
  );
}
